CREATE OR REPLACE FUNCTION public.zatca_claim_credit_note_pih(p_tenant_id uuid, p_note_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
